"""Report fixed F SupCon target comparison from complete immutable evidence."""
import csv,json,statistics,sys
from pathlib import Path
P=Path(sys.argv[1]);data=json.loads((P/'final_collected.json').read_text(encoding='utf8'));audit=json.loads((P/'final_target_recount.json').read_text(encoding='utf8'));result=data['result']
if data['status']!='COLLECTED_COMPLETE' or audit['status']!='VERIFIED' or len(result['records'])!=162 or data['new_steps_recounted']!=66600 or data['new_U_packets']!=5783400:raise ValueError('Complete independent fixed target/source execution evidence required')
S=audit['summary'];C=audit['comparisons'];arms=('BASE','ALL_TX','CROSS_RX');rows=[]
for arm in arms:
 for v in S[arm]['per_seed']:
  cost=next(r for r in result['costs'] if r['arm']==arm and r['model_seed']==v['model_seed']);rows.append(dict(v,source_seconds=cost['source_seconds'],new_epochs=cost['new_epochs'],new_steps=cost['new_steps'],historical_epochs_separate=cost['historical_epochs_separate'],network_parameters=900722,feature_parameters=232033,default_head_parameters=960))
with (P/'per_seed_metrics.csv').open('w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
pairs=[dict(comparison=name,**v) for name,value in C.items() for v in value['per_seed']]
with (P/'paired_differences.csv').open('w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=list(pairs[0]));w.writeheader();w.writerows(pairs)
pct=lambda x:f'{100*x:.4f}'
improved=[a for a in arms[1:] if S[a]['accuracy']['mean']>S['BASE']['accuracy']['mean']]
headline='本轮在固定三种子目标域 clean 测试中观察到平均准确率增益。' if improved else '本轮未获得相对 F 的平均准确率提升。'
lines=['# F＋浅中层同 TX 对比学习：目标域 clean 完整结果','','**'+headline+'**','','性能判断全部来自冻结后的测试集目标域。BASE 复用原 F 三种子匹配结果；ALL_TX、CROSS_RX 各从零训练三种子，每模型 50 轮＝33L＋17U。所有种子在读取新目标汇总前已固定，没有源域性能晋级门槛、另训分类头、目标选模或选择性重跑。','','|条件|seed01|seed02|seed03|目标准确率均值 ± 样本SD|Macro-F1均值 ± SD|最差RX均值|最差day均值|','|---|---|---|---|---|---|---|---|']
for arm in arms:
 s=S[arm];lines.append('|'+arm+'|'+'|'.join(pct(v['accuracy'])+'%' for v in s['per_seed'])+'|'+pct(s['accuracy']['mean'])+'% ± '+pct(s['accuracy']['sample_SD'])+' pp|'+pct(s['macro_f1']['mean'])+'% ± '+pct(s['macro_f1']['sample_SD'])+' pp|'+pct(s['worst_RX']['mean'])+'%|'+pct(s['worst_day']['mean'])+'%|')
lines+=['','|配对比较|seed01／02／03准确率差（百分点）|均值 ± 样本SD（百分点）|正差数|','|---|---|---|---|']
for name,v in C.items():lines.append('|'+name+'|'+' / '.join(f"{p['accuracy_difference_pp']:+.6f}" for p in v['per_seed'])+'|'+f"{v['accuracy_difference_pp']['mean']:+.6f} ± {v['accuracy_difference_pp']['sample_SD']:.6f}"+'|'+str(v['positive_seeds'])+'/3|')
for arm in arms[1:]:
 v=C[arm+'-BASE'];diff=v['accuracy_difference_pp']['mean'];mf=100*(S[arm]['macro_f1']['mean']-S['BASE']['macro_f1']['mean']);lines+=['',arm+' 相对 F 的平均准确率差为 '+f'{diff:+.6f}'+' 个百分点，Macro-F1 差为 '+f'{mf:+.6f}'+' 个百分点，'+str(v['positive_seeds'])+'/3 准确率正差；'+('达到' if S[arm]['accuracy']['mean']>=.84 else '未达到')+' 84% 三种子均值。3 个种子是描述性证据，不据此宣称统计显著或普遍收益。']
direct=C['CROSS_RX-ALL_TX'];lines+=['','CROSS_RX 相对 ALL_TX 的准确率均值差为 '+f"{direct['accuracy_difference_pp']['mean']:+.6f} ± {direct['accuracy_difference_pp']['sample_SD']:.6f}"+' 个百分点，'+str(direct['positive_seeds'])+'/3 正差。当前证据支持两类同 TX 特征对比与 F 配合带来提升；不能仅据这 3 个种子认定跨 RX 筛选本身具有稳定的独立优势。']
lines+=['','历史单路 RAW＋RDrop 条件 A 的匹配三种子均值为 84.340079%；本轮主要配对基线为三路＋统一 Sinc 的 F（84.270238%）。只有超过 F 的局部改善，不自动等于超过 A 或历史最好结果。本轮 ALL_TX、CROSS_RX 均值分别高于 A 0.483135、0.773810 个百分点；该比较同时包含三路、Sinc 方案与新损失的变化，隔离新损失仍使用 F 配对比较。A 属于已有暴露基准参照，不重新训练或重新选择。','','ALL_TX 对当前真实 L 批次中的同 TX 非自身样本建立正对，其他 TX 为负对。CROSS_RX 只将同 TX、不同物理 RX 作为正对，同 TX 同 RX 不作负对。沿用历史温度 0.2、权重 0.1、前 5 轮关闭及后 10 轮线性启用；只复用原 RDrop 的两次实际增强后 L 前向，在 time_down、t2.pool 上取当前批次描述子计算训练损失，4 项取均值。无合法正对或负对的 anchor 安全略过，原随机 L 采样不变。批次均值／标准差只用于训练损失，没有加入 MEAN_VAR／COV 推理分支。','','三路独立 SIG_TIME、joint160、默认 cosine 分类头、原 RDrop alpha1、LS0.01、普通增强、旧门控＋ownEMA＋cos、完整统一 Sinc 更新均保持。辅助损失直接连接特征、不直接连接分类权重；默认头继续按 CE＋RDrop 与骨干联合训练。Sinc 保留 p=p0+25000q、原 cosine 对应物理单位更新、物理 Hz clip5、包含 origin 的一次物理衰减、student／EMA／推理统一坐标及缓存失效逻辑。没有使用前轮负收益的 NORM／BAND 更新。','','|成本／实际执行|BASE|ALL_TX|CROSS_RX|','|---|---|---|---|']
for label,fn in [('新增训练轮数',lambda a:str(sum(r['new_epochs'] for r in rows if r['arm']==a))),('新增优化器步数',lambda a:str(sum(r['new_steps'] for r in rows if r['arm']==a))),('单模型训练秒数均值',lambda a:f"{statistics.mean(r['source_seconds'] for r in rows if r['arm']==a):.2f}"),('总参数／部署特征参数',lambda a:'900722 / 232033'),('额外模型前向／额外推理参数',lambda a:'0 / 0')]:lines.append('|'+label+'|'+'|'.join(fn(a) for a in arms)+'|')
lines+=['','训练秒数受 GPU 与并行负载影响，不能直接解释为固定加速倍率。BASE 的历史 150 轮成本单独列示。r02 完整新增 300 模型轮次、66600 次更新；技术失败 r01 另消耗 30 模型轮次、6660 次已完成更新，两次尝试合计新增 330 模型轮次、73260 次已完成更新。失败尝试未产生新增目标预测或可用于继承的 final50 权重，每个正式 r02 模型仍为从零 50 轮。独立核算全部 66600 次新增更新、5783400 次隐藏标签 U 观测、6×11100 条 Sinc 物理更新记录及 6×11100 条 SupCon 记录，每模型后 9990 步应用、39960 项层位／前向损失。没有额外优化器更新、分类头拟合或 U TX 真值读取。核对全部 9×50 个 epoch 和完整训练日志；只把禁用训练期目标查询时的 nan 占位记为占位，正式预测评分均须有限。','','每行冻结第 50 轮后自动完成 clean 168000 个物理样本的默认头预测，预测完成后由独立 CPU scorer 连接 truth。共 9 行、162 个总体／RX／day／RX-day 混淆矩阵；独立重算整数混淆矩阵、Macro-F1、accuracy、物理 ID 一致性与纠正／新增错误配对差。逻辑评分 1512000 次，其中新增模型预测 1008000 次；原 F 三行预测及评分依法复用。','','历史正收益 SupCon 来自不同的 30 轮 UNIFORM_SSL 配方，只复用了公式，未复用旧权重、单独分类头或其目标成绩作为本轮配对基线。已经暴露的 ManySig clean 测试基准不属于新的独立盲测；本轮不声称新 TX、Phase2、卫星环境或部署性能。全部负结果保留，测试结果不回流调整权重、温度、种子或冻结点。','','执行代码提交：'+data['execution_commit']+'。完整逐种子指标与成本见 per_seed_metrics.csv，配对差见 paired_differences.csv，独立核算见 final_target_recount.json。']
(P/'final_analysis.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
summary=dict(status='ANALYZED',run_id=result['run_id'],performance_basis='frozen target test clean default head',goal_improvement_observed=bool(improved),positive_mean_arms=improved,summary=S,comparisons=C,source_qualification_gate=False,all_three_seeds_frozen=True,negative_results_preserved=True,technical_failed_attempt_extra_epochs=30,technical_failed_attempt_extra_updates=6660,total_new_epochs_including_failure=330,total_new_updates_including_failure=73260,head_fit_updates=0,execution_commit=data['execution_commit'])
(P/'analysis_summary.json').write_text(json.dumps(summary,indent=2,allow_nan=False)+'\n',encoding='utf8');print(json.dumps(dict(status='ANALYZED',positive_mean_arms=improved,target_accuracy={a:S[a]['accuracy'] for a in arms},paired={k:dict(mean=v['accuracy_difference_pp']['mean'],positive_seeds=v['positive_seeds']) for k,v in C.items()})))
